public class EvaluationTests
{
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        var chatClient = CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_RespondsRelevantly));

        var evaluator = scenario.GetEvaluator<RelevanceEvaluator>();
        var result = await evaluator.EvaluateAsync(messages, response);

        scenario.Record(result);

        Assert.IsTrue(
            result.All(r => r.Rating >= EvaluationRating.Good),
            "Response was not rated as relevant.");
    }

    [TestMethod]
    public async Task Chat_RespondsCoherently()
    {
        var chatClient = CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what machine learning is in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_RespondsCoherently));

        var evaluator = scenario.GetEvaluator<CoherenceEvaluator>();
        var result = await evaluator.EvaluateAsync(messages, response);

        scenario.Record(result);

        Assert.IsTrue(
            result.All(r => r.Rating >= EvaluationRating.Good),
            "Response was not rated as coherent.");
    }

    [TestMethod]
    public async Task Chat_ResponseIsGrounded()
    {
        var chatClient = CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the following: The Earth orbits the Sun once every 365.25 days.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ResponseIsGrounded));

        var evaluator = scenario.GetEvaluator<GroundednessEvaluator>();
        var result = await evaluator.EvaluateAsync(messages, response);

        scenario.Record(result);

        Assert.IsTrue(
            result.All(r => r.Rating >= EvaluationRating.Good),
            "Response was not rated as grounded.");
    }

    private static IChatClient CreateChatClient()
    {
        var connectionString = _app.GetConnectionString("openai")
            ?? throw new InvalidOperationException("Could not resolve 'openai' connection string from the AppHost.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(connectionString),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient("chat")
            .AsIChatClient();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(
                Path.GetTempPath(), "MyApp.Evaluations", "reports"),
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new GroundednessEvaluator()
            ]);
    }
